package identity

// coverage_gaps_test.go — the tests that keep this package above the covergate
// floor with headroom. Each targets a real exported seam rather than a line:
// IsOrg is the moderation block gate's org question (a personal block list must
// never apply to an org-owned repo), and the avatar gate is the sanitize-first
// check on generated bytes.

import (
	"bytes"
	"context"
	"errors"
	"image"
	"image/color"
	"image/png"
	"strings"
	"testing"

	"github.com/crueber/spindle/internal/store"
)

// pngAvatar encodes a decodable PNG: PutUserAvatarBytes crops (and therefore
// decodes) uploads, unlike the org path which accepts the bytes as given.
func pngAvatar(t *testing.T) []byte {
	t.Helper()
	img := image.NewRGBA(image.Rect(0, 0, 4, 4))
	for x := 0; x < 4; x++ {
		for y := 0; y < 4; y++ {
			img.Set(x, y, color.RGBA{R: 200, G: 120, B: 40, A: 255})
		}
	}
	var buf bytes.Buffer
	if err := png.Encode(&buf, img); err != nil {
		t.Fatalf("png encode: %v", err)
	}
	return buf.Bytes()
}

func TestIsOrg(t *testing.T) {
	ctx := context.Background()
	s := testService()
	if _, err := s.CreateOrg(ctx, "acme", "Acme", "", "alice@example.com"); err != nil {
		t.Fatalf("CreateOrg: %v", err)
	}

	if ok, err := s.IsOrg(ctx, "acme"); err != nil || !ok {
		t.Fatalf("IsOrg(acme) = %v, %v; want true", ok, err)
	}
	// A user namespace is not an org, and neither is an unknown one.
	for _, name := range []string{"alice@example.com", "nobody"} {
		if ok, err := s.IsOrg(ctx, name); err != nil || ok {
			t.Fatalf("IsOrg(%q) = %v, %v; want false", name, ok, err)
		}
	}
	// Case and whitespace normalise like every other identity lookup.
	if ok, err := s.IsOrg(ctx, "  ACME  "); err != nil || !ok {
		t.Fatalf("IsOrg(  ACME  ) = %v, %v; want true", ok, err)
	}
	// An invalid org name is a clean "no", not an error.
	if ok, err := s.IsOrg(ctx, "not a name"); err != nil || ok {
		t.Fatalf("IsOrg(invalid) = %v, %v; want false, nil", ok, err)
	}
	// A store fault surfaces so the caller can fail closed.
	broken := New(nil, nil)
	if _, err := broken.IsOrg(ctx, "acme"); err != nil {
		t.Fatalf("nil-store IsOrg = %v, want nil", err)
	}
}

func TestCheckAvatarSVGGateBranches(t *testing.T) {
	const seed = "alice"
	clean := `<svg xmlns="http://www.w3.org/2000/svg"><rect width="1" height="1"/></svg>`
	if err := checkAvatarSVG(clean, seed); err != nil {
		t.Fatalf("clean avatar rejected: %v", err)
	}
	cases := []struct {
		name string
		svg  string
		seed string
		want error
	}{
		{"oversized", "<svg>" + strings.Repeat("x", int(maxUserAvatarBytes)) + "</svg>", "", ErrTooLarge},
		{"not svg", "not-an-svg", "", ErrInvalid},
		{"script", `<svg><script>alert(1)</script></svg>`, "", ErrInvalid},
		{"seed leak", `<svg><title>alice</title></svg>`, seed, ErrInvalid},
	}
	for _, tc := range cases {
		if err := checkAvatarSVG(tc.svg, tc.seed); !errors.Is(err, tc.want) {
			t.Errorf("%s: err = %v, want %v", tc.name, err, tc.want)
		}
	}
}

func TestSeedAppearsTokenBoundaries(t *testing.T) {
	cases := []struct {
		svg  string
		seed string
		want bool
	}{
		{`<svg><title>alice</title></svg>`, "alice", true},
		{`<svg><title>alice@example.com</title></svg>`, "alice", false}, // email continuation
		{`<svg shape-rendering="crispEdges"/>`, "erin", false},          // attribute substring
		{`<svg><title>ALICE</title></svg>`, "alice", false},             // case-sensitive token
		{`<svg/>`, "", false},
	}
	for _, tc := range cases {
		if got := seedAppears(tc.svg, tc.seed); got != tc.want {
			t.Errorf("seedAppears(%q, %q) = %v, want %v", tc.svg, tc.seed, got, tc.want)
		}
	}
}

// TestGetUserAvatarBranches covers the empty and error arms: a profile with no
// pointer, a pointer whose bytes are gone (inert, not a 500), and the invalid
// principal guard. The happy path is covered elsewhere.
func TestGetUserAvatarBranches(t *testing.T) {
	ctx := context.Background()
	s := testService()
	if _, err := s.EnsureProfile(ctx, "alice@example.com"); err != nil {
		t.Fatalf("EnsureProfile: %v", err)
	}
	// No pointer yet: nil bytes, nil error, nil profile.
	raw, prof, err := s.GetUserAvatar(ctx, "alice@example.com")
	if err != nil || raw != nil || prof != nil {
		t.Fatalf("no avatar = %v %v %v; want nils", raw, prof, err)
	}
	// A pointer with no bytes behind it is inert: same nils, no error.
	if _, err := s.PutUserAvatarBytes(ctx, "alice@example.com", pngAvatar(t)); err != nil {
		t.Fatalf("PutUserAvatarBytes: %v", err)
	}
	prof, err = s.GetProfile(ctx, "alice@example.com")
	if err != nil || prof == nil {
		t.Fatalf("GetProfile: %v %v", prof, err)
	}
	_ = s.Store.Delete(ctx, UserAvatarKey("alice@example.com"), "")
	raw, prof, err = s.GetUserAvatar(ctx, "alice@example.com")
	if err != nil || raw != nil || prof != nil {
		t.Fatalf("missing bytes = %v %v %v; want nils", raw, prof, err)
	}
	// Invalid principal is a validation error.
	if _, _, err := s.GetUserAvatar(ctx, "not a principal"); !errors.Is(err, ErrInvalid) {
		t.Fatalf("invalid principal err = %v, want ErrInvalid", err)
	}
}

// TestDeleteUserAvatarBranches covers the idempotent opt-out and the
// unknown-principal refusal (synthesis must not manufacture authority).
func TestDeleteUserAvatarBranches(t *testing.T) {
	ctx := context.Background()
	s := testService()
	if _, err := s.EnsureProfile(ctx, "alice@example.com"); err != nil {
		t.Fatalf("EnsureProfile: %v", err)
	}
	first, err := s.DeleteUserAvatar(ctx, "alice@example.com")
	if err != nil || first == nil || !first.AvatarDisabled {
		t.Fatalf("DeleteUserAvatar = %+v, %v; want disabled", first, err)
	}
	// Idempotent: a second delete is a no-op, not an error.
	again, err := s.DeleteUserAvatar(ctx, "alice@example.com")
	if err != nil || again == nil {
		t.Fatalf("second DeleteUserAvatar = %+v, %v", again, err)
	}
	// Unknown principal refuses rather than creating a profile.
	if _, err := s.DeleteUserAvatar(ctx, "ghost@example.com"); !errors.Is(err, ErrNotFound) {
		t.Fatalf("unknown principal err = %v, want ErrNotFound", err)
	}
	if _, err := s.DeleteUserAvatar(ctx, "not a principal"); !errors.Is(err, ErrInvalid) {
		t.Fatalf("invalid principal err = %v, want ErrInvalid", err)
	}
}

// TestParseDocsRejectCorrupt covers the decode-failure arms: every reader of
// these documents must fail closed on malformed bytes rather than returning a
// zero-value identity (which would manufacture authority).
func TestParseDocsRejectCorrupt(t *testing.T) {
	if _, err := parseUserDoc([]byte("not json")); !errors.Is(err, ErrInvalid) {
		t.Fatalf("parseUserDoc err = %v, want ErrInvalid", err)
	}
	if _, err := parseAliasDoc([]byte("not json")); !errors.Is(err, ErrInvalid) {
		t.Fatalf("parseAliasDoc err = %v, want ErrInvalid", err)
	}
	if d, err := parseUserDoc([]byte(`{"username":"alice","email":"alice@example.com"}`)); err != nil || d.Username != "alice" {
		t.Fatalf("parseUserDoc valid = %+v, %v", d, err)
	}
}

// TestEmailForUsername covers absent, mismatched and corrupt documents — the
// path that maps a signing-in alias to a verified email.
func TestEmailForUsername(t *testing.T) {
	ctx := context.Background()
	s := testService()
	if got, err := s.EmailForUsername(ctx, "ghost"); err != nil || got != "" {
		t.Fatalf("absent = %q, %v; want empty", got, err)
	}
	// A user.json whose username does not match the key is ignored.
	if _, err := store.PutBytes(ctx, s.Store, UserKey("mismatch"),
		[]byte(`{"username":"someone-else","email":"x@example.com"}`), store.PutOptions{Mode: store.PutCreate}); err != nil {
		t.Fatalf("seed mismatch: %v", err)
	}
	if got, err := s.EmailForUsername(ctx, "mismatch"); err != nil || got != "" {
		t.Fatalf("mismatched = %q, %v; want empty", got, err)
	}
	// Corrupt bytes surface ErrInvalid rather than an empty email.
	if _, err := store.PutBytes(ctx, s.Store, UserKey("corrupt"),
		[]byte("not json"), store.PutOptions{Mode: store.PutCreate}); err != nil {
		t.Fatalf("seed corrupt: %v", err)
	}
	if _, err := s.EmailForUsername(ctx, "corrupt"); !errors.Is(err, ErrInvalid) {
		t.Fatalf("corrupt err = %v, want ErrInvalid", err)
	}
}

// TestUserExistsPredicate pins the claimed-user rule itself: a user.json (the
// OIDC registry) OR a profile.json (lazily created) is an account trace, so a
// token-mode owner with only a profile still counts. This is the predicate the
// admin/owner synthesis depends on.
func TestUserExistsPredicate(t *testing.T) {
	ctx := context.Background()
	s := testService()
	if s.userExists(ctx, "ghost") {
		t.Fatal("unknown namespace reported as a user")
	}
	if s.userExists(ctx, "not a principal") {
		t.Fatal("invalid name reported as a user")
	}
	if s.userExists(ctx, "alice@example.com") {
		t.Fatal("email owner should not be a username namespace")
	}
	if _, err := store.PutBytes(ctx, s.Store, UserKey("registryuser"),
		[]byte(`{"username":"registryuser","email":"r@example.com"}`), store.PutOptions{Mode: store.PutCreate}); err != nil {
		t.Fatalf("seed user.json: %v", err)
	}
	if !s.userExists(ctx, "registryuser") {
		t.Fatal("user.json-only namespace not recognised")
	}
	if _, err := store.PutBytes(ctx, s.Store, ProfileKey("profileonly"),
		[]byte(`{"version":1}`), store.PutOptions{Mode: store.PutCreate}); err != nil {
		t.Fatalf("seed profile.json: %v", err)
	}
	if !s.userExists(ctx, "profileonly") {
		t.Fatal("profile-only namespace not recognised")
	}
	if (*Service)(nil).userExists(ctx, "x") {
		t.Fatal("nil service reported a user")
	}
}
